// Topic list mirrors docs/content/keyword-backlog.md in Techvia-TMS-Marketing:
// Tier 1 + Tier 2 rows in the 2026-07 / 2026-08 windows, in document order.
// The slug is authoritative and is used verbatim - nothing slugifies a title anymore.
// ponytail: embedded array, not a database. Becomes a Postgres table when n8n moves
// off this laptop onto the server; until then git is the version control for it.
const TOPICS = [
  { slug: "tms-software-pricing-small-fleets", keyword: "TMS software pricing for small fleets", angle: "What TMS actually costs, and why per-user pricing punishes growing fleets", hook: "flat $199/mo, unlimited users" },
  { slug: "tms-vs-spreadsheets-freight-brokers", keyword: "TMS vs spreadsheets for freight brokers", angle: "The real cost of the spreadsheet: errors, double-entry, no audit trail", hook: "the whole platform" },
  { slug: "tms-for-10-truck-fleet", keyword: "TMS for a 10 truck fleet", angle: "Sizing guide: what you need at 10 trucks that you didn't at 3", hook: "dispatch board, 30-day trial" },
  { slug: "tms-for-25-truck-fleet", keyword: "TMS for a 25 truck fleet", angle: "The breakpoint where spreadsheets stop working", hook: "dispatch + settlements" },
  { slug: "trucking-dispatch-software-free-trial", keyword: "trucking dispatch software free trial", angle: "What to actually test during a trial, as a 10-point checklist", hook: "30-day trial, no card" },
  { slug: "how-to-choose-a-tms-checklist", keyword: "how to choose a TMS - buyer's checklist", angle: "Vendor-neutral checklist, including the questions that make bad vendors squirm", hook: "positions us as the honest one" },
  { slug: "tms-with-edi-204-small-brokers", keyword: "TMS with EDI 204 for small brokers", angle: "EDI is sold as enterprise-only; it isn't", hook: "EDI X12 204 tenders becoming loads" },
  { slug: "dispatch-software-gps-tracking-small-carriers", keyword: "dispatch software with GPS tracking for small carriers", angle: "Tracking without buying a full telematics contract", hook: "driver magic links + Samsara ELD" },
  { slug: "tms-for-brokers-and-carriers", keyword: "TMS for freight brokers and carriers (both sides)", angle: "Running brokerage and assets on one system instead of two", hook: "multi-tenant, holding companies" },
  { slug: "stop-running-dispatch-on-spreadsheets", keyword: "how to stop running dispatch on spreadsheets", angle: "Migration path week by week; the honest version admits what breaks", hook: "dispatch board" },
  { slug: "rate-confirmation-ratecon-workflow", keyword: "rate confirmation (RateCon) workflow", angle: "From quote to signed RateCon without email ping-pong", hook: "quotes module" },
  { slug: "carrier-onboarding-checklist-brokers", keyword: "carrier onboarding checklist for brokers", angle: "Packet, authority, insurance, W-9: the full checklist as a real checklist", hook: "carriers + compliance" },
  { slug: "how-to-reduce-deadhead-empty-miles", keyword: "how to reduce deadhead / empty miles", angle: "Practical levers, and how to work out what deadhead is costing a fleet", hook: "AI Dispatcher margin/deadhead ranking" },
  { slug: "how-to-reduce-dispatcher-workload", keyword: "how to reduce dispatcher workload", angle: "Where a dispatcher's day actually goes, and what to automate first", hook: "dispatch + AI Dispatcher" },
  { slug: "proof-of-delivery-collection-workflow", keyword: "proof of delivery (POD) collection workflow", angle: "Getting PODs off the driver's phone and into billing the same day", hook: "driver magic links" },
];

// content/posts/ is the record of what is published - no status column to keep in sync.
// Filenames are {YYYY-MM-DD}-{slug}.md, so strip the date and compare slugs exactly;
// substring matching would misfire the moment one slug is a prefix of another.
const publishedSlugs = new Set(
  $('List Published Files').all()
    .map(i => String(i.json.name || ''))
    .filter(n => n.endsWith('.md'))
    .map(n => n.replace(/^\d{4}-\d{2}-\d{2}-/, '').replace(/\.md$/, ''))
);

const row = TOPICS.find(t => !publishedSlugs.has(t.slug));
const today = new Date().toISOString().split('T')[0];

if (!row) {
  return [{ json: { exhausted: true, today, checked: TOPICS.length } }];
}

// Give the writer a clock. Three June posts carried a hallucinated "2024" because
// the model was guessing the date.
const year = today.slice(0, 4);
const recentTitles = $input.all().map(i => i.json.title).filter(Boolean).slice(0, 30);

const writerSystem = "You are a senior freight operations writer for Techvia (techvia.software). Techvia TMS is a transportation management system for small-to-medium US freight brokers and carriers: drag-and-drop dispatch board, fleet and drivers, live GPS tracking, customer invoicing, driver and carrier settlements, and EDI load tenders. Write a complete, SEO-optimised Hugo blog post in markdown for brokers, dispatchers, and carriers. Voice: human and practical. Vary sentence length; use first-person team voice (\"we built Techvia TMS because...\", \"the dispatchers we talk to...\"); use concrete freight detail (stops, RateCons, PODs, deadhead, detention). 900-1200 words. Use ## and ### headings and at most one bulleted list. NEVER use these phrases: \"in todays fast-paced world\", \"delve\", \"moreover\", \"furthermore\", \"in conclusion\", \"unlock the power\", \"ever-evolving\", \"landscape\", \"navigating the\". Weave Techvia TMS in once where it genuinely answers the problem, and end with a natural call-to-action paragraph linking to https://www.techvia.software/products/tms . Do not stuff the product everywhere. NEVER invent statistics, percentages, dollar figures or survey results: cite a number only if you can attribute it to a named public source (FMCSA, ATA, DAT, BLS), otherwise make the argument without a number." +
  ' Today is ' + today + '. The current year is ' + year + ' and this post publishes on ' + today +
  '. Do not put a year in the title, and never state a year other than ' + year + '.' +
  ' Articles already on this blog, so do not rewrite one of these: ' + JSON.stringify(recentTitles) + '.' +
  ' Output ONLY the markdown body (no frontmatter).';

const writerUser = 'Write the post. Target search query: "' + row.keyword + '". Angle: ' + row.angle +
  '. Product hook to land naturally: ' + row.hook +
  '. Audience: US freight brokers and carriers running 10-75 power units.' +
  ' Techvia TMS is $199/mo for unlimited users with a 30-day trial and no card required.';

return [{ json: { exhausted: false, topic_slug: row.slug, topic_keyword: row.keyword, publish_date: today, writerSystem, writerUser } }];

const pick = $('Pick Topic').first().json;
const today = pick.publish_date;
const slug = pick.topic_slug;
let body = $('Write Article').item.json.choices[0].message.content;
const meta = JSON.parse($json.choices[0].message.content.replace(/```json\n?|```/g, '').trim());

// The writer usually opens with an H1 duplicating the frontmatter title, and PaperMod
// renders the frontmatter one - so lift it out and use it instead of shipping two titles.
const h1 = body.match(/^\s*#\s+(.+)$/m);
if (h1) body = body.replace(h1[0], '').trimStart();
const title = String(meta.title || (h1 && h1[1]) || pick.topic_keyword).trim();

const q = s => String(s).replace(/"/g, '\\"');
const desc = String(meta.seo_description || '').substring(0, 150);
const tags = Array.isArray(meta.tags) ? meta.tags : [];
const category = meta.category || 'TMS';
const filename = today + '-' + slug + '.md';
const fm = [
  '---',
  'title: "' + q(title) + '"',
  'date: ' + today,
  'draft: false',
  'tags: ' + JSON.stringify(tags),
  'categories: ["' + category + '"]',
  'description: "' + q(desc) + '"',
  'showToc: true',
  '---', '', ''
].join('\n');
return [{ json: { filename, markdown: fm + body, slug, title, body, post_path: 'content/posts/' + filename } }];

const a = $('Assemble Markdown').first().json;
const url = 'https://blogs.techvia.software/posts/' + a.filename.replace(/\.md$/, '') + '/';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const out = [{ json: { text: '<b>Published: ' + esc(a.title) + '</b>\n' + esc(url) + '\n\nCTA -> /products/tms. Full text below - reply to Nikesh if it needs draft:true.' } }];

const LIMIT = 3500;
let buf = '';
for (const para of String(a.body).split('\n\n')) {
  if (buf && (buf.length + para.length + 2) > LIMIT) { out.push({ json: { text: esc(buf) } }); buf = ''; }
  buf = buf ? buf + '\n\n' + para : para;
  while (buf.length > LIMIT) { out.push({ json: { text: esc(buf.slice(0, LIMIT)) } }); buf = buf.slice(LIMIT); }
}
if (buf.trim()) out.push({ json: { text: esc(buf) } });
return out;
